import React, { useState } from 'react';
import logo from '../../../assets/logo.png';

function Navbar() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  return (
    <header className="bg-[#FDF8F3] border-b border-[#E1D5C9] p-4">
      <div className="flex items-center justify-between flex-wrap md:flex-nowrap">
        {/* Logo */}
        <img src={logo} alt="Logo" className="h-12" />

        {/* Mobile Menu Toggle */}
        <div className="ml-auto md:hidden">
          <button
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            className="text-2xl font-bold"
          >
            ☰
          </button>
        </div>

        {/* Nav Links */}
        <nav
          className={`w-full md:flex md:justify-center md:items-center md:gap-6 md:w-auto ${
            isMenuOpen ? 'block mt-4' : 'hidden'
          }`}
        >
          <a href="#" className="text-[#f48f0f] text-[clamp(0.9rem,2vw,1.1rem)] font-semibold px-2">
            Home
          </a>
          <a href="#" className="text-[#292929] text-[clamp(0.9rem,2vw,1.1rem)] font-semibold px-2">
            About
          </a>
          <a href="#" className="text-[#292929] text-[clamp(0.9rem,2vw,1.1rem)] font-semibold px-2">
            Gallery
          </a>
          <a href="#" className="text-[#292929] text-[clamp(0.9rem,2vw,1.1rem)] font-semibold px-2">
            Education
          </a>
        </nav>

        {/* Button */}
        <div className="hidden md:block">
          <button className="bg-[#F48F0F] text-[#292929] px-4 py-2 rounded-full font-semibold text-[clamp(0.9rem,2vw,1rem)]">
            Become a member
          </button>
        </div>

        {/* Mobile Button */}
        {isMenuOpen && (
          <div className="w-full flex justify-center mt-4 md:hidden">
            <button className="bg-[#F48F0F] text-[#292929] px-4 py-2 rounded-full font-semibold text-[clamp(0.9rem,2vw,1rem)]">
              Become a member
            </button>
          </div>
        )}
      </div>
    </header>
  );
}

export default Navbar;
